sql.if:
and (
    mo.assigned_agent_id = #{agentId}
    or mo.user_id = #{agentId}
    or su.parent_user_id = #{agentId}
    or (mo.assigned_agent_id is null and su.create_by = #{agentUsername})
    or exists (
        select 1
        from sys_user agent_u
        inner join sys_user_role aur on aur.user_id = agent_u.user_id
        inner join sys_role ar on ar.role_id = aur.role_id and ar.role_key in ('agent', 'mark_agent')
        where agent_u.user_id = #{agentId}
          and agent_u.del_flag = '0'
          and agent_u.rel_mark_template is not null
          and agent_u.rel_mark_template > 0
          and su.rel_mark_template = agent_u.rel_mark_template
    )
    or exists (
        select 1
        from mark_platform_template mpt
        where mpt.id = su.rel_mark_template
          and mpt.owner_user_id = #{agentId}
          and mpt.status = '0'
    )
)

mapper.select:
select count(*)
from sys_user su
where su.user_id = #{userId}
  and su.del_flag = '0'
  and (
    #{isAdmin} = true
    or su.user_id = #{agentId}
    or su.parent_user_id = #{agentId}
    or su.create_by = #{agentUsername}
    or exists (
        select 1
        from sys_user agent_u
        inner join sys_user_role aur on aur.user_id = agent_u.user_id
        inner join sys_role ar on ar.role_id = aur.role_id and ar.role_key in ('agent', 'mark_agent')
        where agent_u.user_id = #{agentId}
          and agent_u.del_flag = '0'
          and agent_u.rel_mark_template is not null
          and agent_u.rel_mark_template > 0
          and su.rel_mark_template = agent_u.rel_mark_template
    )
    or exists (
        select 1 from mark_platform_template mpt
        where mpt.id = su.rel_mark_template
          and mpt.owner_user_id = #{agentId}
          and mpt.status = '0'
    )
  )
